// Generates public/_headers (Netlify, Cloudflare Pages) and vercel.json from
// deploy/security-headers.json. Run: node scripts/gen-headers.mjs
import { readFileSync, writeFileSync } from "node:fs";

const { headers } = JSON.parse(readFileSync(new URL("../deploy/security-headers.json", import.meta.url), "utf8"));
const entries = Object.entries(headers);

const netlify = [
  "# Generated by scripts/gen-headers.mjs from deploy/security-headers.json. Do not edit by hand.",
  "/*",
  ...entries.map(([k, v]) => `  ${k}: ${v}`),
  "",
  "/assets/*",
  "  Cache-Control: public, max-age=31536000, immutable",
  "",
  "/index.html",
  "  Cache-Control: no-cache",
  "",
].join("\n");
writeFileSync(new URL("../public/_headers", import.meta.url), netlify);

const vercel = {
  $schema: "https://openapi.vercel.sh/vercel.json",
  rewrites: [{ source: "/((?!assets/|fonts/|.*\\.[a-z0-9]+$).*)", destination: "/index.html" }],
  headers: [
    { source: "/(.*)", headers: entries.map(([key, value]) => ({ key, value })) },
    { source: "/assets/(.*)", headers: [{ key: "Cache-Control", value: "public, max-age=31536000, immutable" }] },
  ],
};
writeFileSync(new URL("../vercel.json", import.meta.url), JSON.stringify(vercel, null, 2) + "\n");
console.log("wrote public/_headers and vercel.json");
